mapper.select:
SELECT b.NAME as assetName,c.NAME as eventTypeName,a.id,a.ASSET_ID as assetId,
a.FLAG ,a.ALARM_CODE as alarmCode ,a.EVENT_TYPE_ID as eventTypeId,a.CREATE_TIME as createTime,
a.creator,a.TYPE_MARK as typeMark
FROM ALARM_WHITE_LIST a
left join ASSET b on a.ASSET_ID = b.id
left join ALARM_EVENT_TYPE c on c.ID =a.EVENT_TYPE_ID


        and b.name like concat(concat('%',#{query.assetName}),'%')


        and a.ALARM_CODE = #{query.alarmCode}


        and a.EVENT_TYPE_ID = #{query.eventTypeId}




        order by a.${query.orderBy}


        order by a.CREATE_TIME




        ${query.sort}


        desc
